def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The singleton marker identifies the junction. The corner-bar rays
    # extend inward along the bar's aligned row/column; marker becomes 4.
    marker = next(((r, c) for r in range(h) for c in range(w)
                   if grid[r][c] not in (0, 1, 3, 6)), None)
    if marker is None:
        return out
    r, c = marker
    color = grid[r][c]
    bars = [(y, x) for y in range(h) for x in range(w) if grid[y][x] == 6]
    # Find the two horizontal bar components and their inner endpoints.
    bars = []
    for rr in range(h):
        xs = [cc for cc in range(w) if grid[rr][cc] == 6]
        if xs:
            bars.append((rr, min(xs), max(xs)))
    if len(bars) >= 2:
        top, bottom = min(bars), max(bars)
        # Top-left bar has a ray through the rightmost point of its run.
        for rr in range(top[0] + 1, h):
            if grid[rr][top[2]] == 0:
                out[rr][top[2]] = color
        # Bottom-right bar has a ray through the leftmost point of its run.
        for rr in range(bottom[0] - 1, -1, -1):
            if grid[rr][bottom[1]] == 0:
                out[rr][bottom[1]] = color
    # The marker's row also projects rightward to the edge.
    for cc in range(c + 1, w):
        if grid[r][cc] == 0:
            out[r][cc] = color
    out[r][c] = 4
    out[r][c] = 4
    return out

