cat > /home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/seen-3/play/users/u043/system/state/workspace/programs/task-cc637199.py <<'PY'
def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Background corridor determined by the marker and corner-bar endpoints.
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 1, 3, 6)]
    if not markers:
        return out
    r, c, color = markers[0]
    # Extend the singleton marker's column upward and its row rightward;
    # recolor the singleton to 4, matching the demonstrated ray convention.
    for y in range(r):
        if grid[y][c] == 0:
            out[y][c] = color
    for x in range(c + 1, w):
        if grid[r][x] == 0:
            out[r][x] = color
    out[r][c] = 4
    return out
