def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Corner bars mark vertical tiling bands. Fill the area between each
    # bar and the opposite side using the 1/0 pattern indicated by markers.
    # First convert isolated marker 6 to 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                out[r][c] = 4
    # Pattern of holes is a checker-like pair of vertical lines. Replicate
    # the sparse 3-color motif down the interior as a pair of columns.
    # Use the top bar's inner end as the right column and bottom bar's
    # inner end as the left column, extending across the intervening rows.
