def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The singleton 6 is the center of a four-way pattern; recolor it 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                out[r][c] = 4
    # Bars at opposite corners propagate repeated foreground motifs inward.
    # For the top-right bar, fill its vertical column downward; bottom-left
    # bar fills its vertical column upward, while preserving the marker.
    top = [c for c,v in enumerate(grid[0]) if v == 3]
    bottom = [c for c,v in enumerate(grid[-1]) if v == 3]
    if top:
        c = max(top)
        for r in range(1,h):
            if grid[r][c] == 1: out[r][c] = 3
    if bottom:
        c = min(bottom)
        for r in range(h-1):
            if grid[r][c] == 1: out[r][c] = 3
    return out

