    h, w = len(grid), len(grid[0])
    # A singleton marker is the junction of the extended pattern. Continue
    # its color along the lane aligned with the opposing edge bar; mark it 4.
    marker = next(((r, c, grid[r][c]) for r in range(h) for c in range(w)
                   if grid[r][c] not in (1, 3)), None)
    if marker is None:
        return out
    r, c, color = marker
    for rr in range(h):
        if rr != r and grid[rr][c] == 1:
            out[rr][c] = color
    out[r][c] = 4
    return out

