def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The 3-cell corner bars establish two vertical lanes: the rightmost
    # cell of the top bar and the leftmost cell of the bottom bar. Continue
    # the bar color along those lanes; change the interior 6 marker to 4.
    bars = [(r, [c for c, value in enumerate(row) if value == 3])
            for r, row in enumerate(grid) if row.count(3) >= 3]
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if len(bars) >= 2:
        top = min(bars, key=lambda item: item[0])
        bottom = max(bars, key=lambda item: item[0])
        for r in range(top[0] + 1, h):
            if grid[r][max(top[1])] == 1:
                out[r][max(top[1])] = 3
        for r in range(bottom[0] - 1, -1, -1):
            if grid[r][min(bottom[1])] == 1:
                out[r][min(bottom[1])] = 3
    for r, c in seeds:
        out[r][c] = 4
    return out

